head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > editFormat]<br/>컴포넌트에 값을 입력중이거나 값이 표시될때 적용할 포맷을 마스크 문자로 설정합니다.",
    "validation" : [        
        "포맷을 # 로 설정 시 '0~9' 의 숫자만 입력할 수 있습니다.",
        "포맷을 A 로 설정 시 'A~Z' 의 대문자 알파벳만 입력할 수 있습니다.",
        "포맷을 a 로 설정 시 'a~z' 의 소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 Z 로 설정 시 '0~9', 'A~Z' 의 숫자와 대문자 알파벳만 입력할 수 있습니다.",
        "포맷을 z 로 설정 시 '0~9', 'a~z' 의 숫자와 소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 S 로 설정 시 'a~z', 'A~Z' 의 대/소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 X,9 로 설정 시 '0~9', 'a~z,A~Z' 의 숫자와 대/소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 * 로 설정 시 '0~9', 'a~z,A~Z', ~!@#$ 등 의 숫자와 대/소문자 알파벳, 특수문자를 입력할 수 있습니다.",
        "포맷을 K 로 설정 시 'ㄱ~ㅎ,ㅏ~ㅣ,가~힣' 의 모든 한글만 입력할 수 있습니다. (다른 마스크 문자와 함께 사용할 수 없습니다)",
        "포맷을 || 로 설정 시 한 개 이상의 포맷을 정의할 때 포맷의 구분자로 사용하는 특수 기호입니다.",
        "포맷을 {,} 로 설정 시 한 개 이상의 포맷을 정의할 때 포맷의 구분자로 사용하는 특수 기호입니다.",
        "포맷을 ! 로 설정 시 마스크 문자와 특수 기호를 이스케이프 처리하는 특수 기호입니다.",
        "입력 문자가 마스크 문자와 맞지 않으면 입력되지 않습니다.",
        "InputBox 의 실제 입력값은 editFormat 속성의 포맷이 제거된 상태로 저장됩니다.",
        "입력값에 맞춰 마스크 문자가 왼쪽부터 매칭되며 일반 문자가 설정된 경우 입력이 진행되며 자동으로 표시되고 해당 문자는 수정할 수 없습니다.",
        "'{,}' 기호로 마스킹 처리된 범위에 일반 문자가 있는 경우 해당 문자는 마스킹 되지 않고 그대로 표시됩니다.",
        "'||' 기호로 다중 포맷을 설정했을때 마스크 문자의 갯수가 동일한 포맷이 있는 경우 먼저 정의한 포맷이 사용됩니다.",
        "setValue() 메소드 또는 붙여넣기로 값을 입력할때, 입력값이 마스크 문자의 갯수와 형식에 일치하지 않으면 설정되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_edit = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.get_text_display = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("12AZaz0Z0zaZ");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
}

